public static class AgentProjectToolsTests {
static int failures; static void Check(bool ok,string message){if(!ok)throw new Exception(message);} static void Run(string name,Func<Task> test){try{test().GetAwaiter().GetResult();Console.WriteLine("PASS "+name);}catch(Exception e){failures++;Console.WriteLine("FAIL "+name+": "+e);}}
static string J(object o){return new JavaScriptSerializer().Serialize(o);} static AgentQuestionRequest Request(string session,string call){return new AgentQuestionRequest{SessionId=session,TaskId="task",CallId=call,Question="Choose",Options=new[]{"one","two"}};}
static async Task Cancelled(Task task){try{await task;throw new Exception("Expected cancellation");}catch(OperationCanceledException){}}
static void Git(string root,string arguments){using(var p=Process.Start(new ProcessStartInfo("git.exe",arguments){WorkingDirectory=root,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true})){string output=p.StandardOutput.ReadToEnd()+p.StandardError.ReadToEnd();if(!p.WaitForExit(10000)||p.ExitCode!=0)throw new Exception("Fixture Git failed: "+output);}}
public static int Main(string[] args){if(Path.GetFileName(System.Reflection.Assembly.GetExecutingAssembly().Location)=="filter-probe.exe"){File.AppendAllText("filter-ran.txt","executed\n");return 0;}if(args.Length>0&&(args[0]=="--no-pager"||args[0]=="--git-child")){if(args[0]=="--no-pager"){using(var child=Process.Start(new ProcessStartInfo(System.Reflection.Assembly.GetExecutingAssembly().Location,"--git-child"){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=Environment.CurrentDirectory})){File.WriteAllText("fake-git-child.pid",child.Id.ToString());File.WriteAllText("fake-git-parent.pid",Process.GetCurrentProcess().Id.ToString());Thread.Sleep(30000);}}else{Thread.Sleep(2000);File.WriteAllText("fake-git-child.pid",Process.GetCurrentProcess().Id.ToString());Thread.Sleep(30000);}return 0;}
Run("project tools share read only catalogue",async delegate{foreach(string name in new[]{"ask_user","inspect_image","git_status","git_diff","git_log"})Check(AgentToolCatalog.Definitions.Any(t=>t.Name==name&&t.ReadOnly),"Missing readonly tool: "+name);Check(!AgentToolCatalog.IsReadOnly("generate_image"),"generation must not be plan tool");await Task.FromResult(0);});
Run("headless ask_user explains missing input host",async delegate{using(var f=new Folder())using(var ws=new AgentWorkspace(f.Path)){string r=await ws.ExecuteAsync("ask_user","{\"question\":\"Which target?\"}",CancellationToken.None);Check(r.Contains("交互"),r);Check(!ws.AvailableToolNames.Contains("ask_user"),"headless question exposed");}});
Run("question first answer and original session isolation",async delegate{using(var host=new AgentQuestionController()){var request=Request("first","call");var wait=host.AskAsync(request,CancellationToken.None);request.Options[0]="mutated";Check(!host.Submit("other","task","call",new AgentQuestionAnswer{OptionIndex=0}),"cross-session answer accepted");Check(!host.Submit("first","other","call",new AgentQuestionAnswer{OptionIndex=0}),"cross-task answer accepted");Check(host.Submit("first","task","call",new AgentQuestionAnswer{OptionIndex=0}),"valid answer rejected");Check(!host.Submit("first","task","call",new AgentQuestionAnswer{Text="late"}),"duplicate answer accepted");var answer=await wait;Check(answer.Text=="one"&&answer.OptionIndex==0,"answer or snapshot changed");Check(host.Requests.Count==0,"pending leaked");}});
Run("question free answer cancellation and window lifetime",async delegate{using(var host=new AgentQuestionController()){var req=Request("first","free");req.Options=new string[0];var wait=host.AskAsync(req,CancellationToken.None);Check(host.Submit("first","task","free",new AgentQuestionAnswer{Text=" custom "}),"free answer rejected");Check((await wait).Text=="custom","free answer lost");using(var ct=new CancellationTokenSource()){var pending=host.AskAsync(Request("first","cancel"),ct.Token);ct.Cancel();await Cancelled(pending);}var archived=host.AskAsync(Request("archived","a"),CancellationToken.None);var live=host.AskAsync(Request("live","b"),CancellationToken.None);host.CancelSession("archived");await Cancelled(archived);Check(!live.IsCompleted,"other session cancelled");host.Dispose();await Cancelled(live);Check(host.Requests.Count==0,"close leaked pending requests");}});
Run("workspace questions bind stable identity and remain distinct from approvals",async delegate{using(var f=new Folder())using(var host=new AgentQuestionController())using(var ws=new AgentWorkspace(f.Path)){var model=new AgentSessionModel("session","project","conversation");ws.ConfigureKernel(AgentPermissionRuntime.DefaultWorkspacePolicy(),null,null,null,"task",model);ws.QuestionProvider=host;var answer=ws.ExecuteAsync("ask_user",J(new{question="Target?",options=new[]{"A","B"},allow_free_input=false}),"stable",CancellationToken.None);for(int i=0;i<100&&host.Requests.Count==0;i++)await Task.Delay(10);Check(host.Requests.Count==1,"question not presented");Check(!host.Submit("session","task","stable",new AgentQuestionAnswer{Text="free"}),"disabled free input accepted");Check(host.Submit("session","task","stable",new AgentQuestionAnswer{OptionIndex=1}),"choice rejected");Check((await answer).Contains("B"),"choice lost");Check(AgentPermissionRuntime.ActionForTool("ask_user")=="read","question changes permission action");}});
Run("workspace disposal cancels unanswered questions",async delegate{using(var f=new Folder())using(var host=new AgentQuestionController()){var ws=new AgentWorkspace(f.Path);ws.ConfigureKernel(AgentPermissionRuntime.DefaultWorkspacePolicy(),null,null,null,"task",new AgentSessionModel("session","project","conversation"));ws.QuestionProvider=host;var wait=ws.ExecuteAsync("ask_user",J(new{question="Target?"}),"dispose",CancellationToken.None);ws.Dispose();await Cancelled(wait);Check(host.Requests.Count==0,"question remains after workspace disposal");}});
Run("inspect_image sends image channel with metadata only in tool text",async delegate{using(var f=new Folder())using(var ws=new AgentWorkspace(f.Path)){string path=System.IO.Path.Combine(f.Path,"image.png");using(var image=new System.Drawing.Bitmap(2,3))image.Save(path,System.Drawing.Imaging.ImageFormat.Png);ws.ConfigureProvider("openai","gpt-4o");string text=await ws.ExecuteAsync("inspect_image",J(new{path="image.png",question="What color?"}),"image",CancellationToken.None);Check(text.Contains("\"width\":2")&&text.Contains("\"height\":3"),text);Check(!text.Contains("base64")&&!text.Contains("iVBOR"),"bytes leaked in tool text");var result=ws.TakeInspectionResult("image");Check(result!=null&&result.Width==2&&result.Height==3,"image channel missing");Check(J(result.Content(text,false)).Contains("image_url"),"OpenAI image missing");Check(J(result.Content(text,true)).Contains("\"type\":\"image\""),"Anthropic image missing");Check(ws.TakeInspectionResult("image")==null,"image bytes retained after consuming");}});
Run("inspect_image refuses linked files oversized dimensions and cancellation",async delegate{using(var f=new Folder()){string root=System.IO.Path.Combine(f.Path,"workspace");Directory.CreateDirectory(root);string original=System.IO.Path.Combine(f.Path,"outside.png");using(var image=new System.Drawing.Bitmap(2,2))image.Save(original,System.Drawing.Imaging.ImageFormat.Png);Check(CreateHardLink(System.IO.Path.Combine(root,"linked.png"),original,IntPtr.Zero),"hardlink fixture failed");using(var image=new System.Drawing.Bitmap(16385,1))image.Save(System.IO.Path.Combine(root,"wide.png"),System.Drawing.Imaging.ImageFormat.Png);using(var ws=new AgentWorkspace(root)){ws.ConfigureProvider("openai","gpt-4o");Check((await ws.ExecuteAsync("inspect_image",J(new{path="linked.png"}),CancellationToken.None)).StartsWith("错误："),"external hardlink was read");Check((await ws.ExecuteAsync("inspect_image",J(new{path="wide.png"}),CancellationToken.None)).StartsWith("错误："),"oversized dimensions accepted");using(var ct=new CancellationTokenSource()){ct.Cancel();try{await ws.ExecuteAsync("inspect_image",J(new{path="wide.png"}),ct.Token);throw new Exception("cancelled image was executed");}catch(OperationCanceledException){}}}}});
Run("image dimensions cover JPEG GIF and WebP signatures",async delegate{using(var image=new System.Drawing.Bitmap(4,5)){foreach(bool gif in new[]{false,true})using(var stream=new MemoryStream()){image.Save(stream,gif?System.Drawing.Imaging.ImageFormat.Gif:System.Drawing.Imaging.ImageFormat.Jpeg);var parsed=AgentImageInspection.Parse(gif?"test.gif":"test.jpg",stream.ToArray(),"");Check(parsed.Width==4&&parsed.Height==5,"wrong GIF/JPEG dimensions");}}byte[] webp=Convert.FromBase64String("UklGRiIAAABXRUJQVlA4IBYAAAAwAQCdASoBAAEADsD+JaQAA3AAAAAA");var loss=AgentImageInspection.Parse("test.webp",webp,"");Check(loss.Width==1&&loss.Height==1,"wrong WebP dimensions");await Task.FromResult(0);});
Run("inspect_image rejects damaged signatures limits escapes and text models",async delegate{using(var f=new Folder())using(var ws=new AgentWorkspace(f.Path)){ws.ConfigureProvider("openai","gpt-4o");File.WriteAllBytes(System.IO.Path.Combine(f.Path,"broken.png"),new byte[]{137,80,78,71,13,10,26,10,0,0,0,0,0,0});var bad=await ws.ExecuteAsync("inspect_image",J(new{path="broken.png"}),CancellationToken.None);Check(bad.StartsWith("错误："),bad);var escape=await ws.ExecuteAsync("inspect_image",J(new{path="../outside.png"}),CancellationToken.None);Check(escape.StartsWith("错误："),escape);using(var large=File.Create(System.IO.Path.Combine(f.Path,"large.png")))large.SetLength(AgentImageInspection.MaximumBytes+1);Check((await ws.ExecuteAsync("inspect_image",J(new{path="large.png"}),CancellationToken.None)).StartsWith("错误："),"oversized image accepted");ws.ConfigureCapabilities(new AgentCapabilitySnapshot(CapabilitySupport.Supported,CapabilitySupport.Unsupported,true,false,32768,"test","test"));Check(!ws.AvailableToolNames.Contains("inspect_image"),"text model schema contains image tool");Check((await ws.ExecuteAsync("inspect_image",J(new{path="broken.png"}),CancellationToken.None)).Contains("不支持图片理解"),"text-only capability not explained");}});
Run("Git status diff log are bounded read only and literal paths",async delegate{using(var f=new Folder()){Git(f.Path,"init -q");Git(f.Path,"config user.name Fixture");Git(f.Path,"config user.email fixture@example.invalid");File.WriteAllText(System.IO.Path.Combine(f.Path,"tracked.txt"),"before\n");Git(f.Path,"add -- tracked.txt");Git(f.Path,"commit -qm baseline");byte[] index=File.ReadAllBytes(System.IO.Path.Combine(f.Path,".git/index"));File.WriteAllText(System.IO.Path.Combine(f.Path,"tracked.txt"),"after\n");File.WriteAllText(System.IO.Path.Combine(f.Path,"--output=escaped"),"literal\n");Git(f.Path,"config diff.external \"cmd /c echo EXECUTED>external-ran\"");Git(f.Path,"config core.fsmonitor \"cmd /c echo EXECUTED>monitor-ran\"");Git(f.Path,"config diff.fixture.textconv \"cmd /c echo EXECUTED>textconv-ran\"");File.WriteAllText(System.IO.Path.Combine(f.Path,".gitattributes"),"tracked.txt diff=fixture\n");using(var ws=new AgentWorkspace(f.Path)){Check((await ws.ExecuteAsync("git_status","{}",CancellationToken.None)).Contains("tracked.txt"),"modified file omitted");string diff=await ws.ExecuteAsync("git_diff","{}",CancellationToken.None);Check(diff.Contains("+after")&&diff.Contains("未跟踪"),diff);Check((await ws.ExecuteAsync("git_diff",J(new{path="--output=escaped"}),CancellationToken.None)).Contains("未跟踪"),"literal option path failed");Check((await ws.ExecuteAsync("git_diff",J(new{scope="--output=bad"}),CancellationToken.None)).StartsWith("错误："),"scope injection accepted");Check((await ws.ExecuteAsync("git_log",J(new{limit=1}),CancellationToken.None)).Contains("baseline"),"commit missing");Check(index.SequenceEqual(File.ReadAllBytes(System.IO.Path.Combine(f.Path,".git/index"))),"index changed during reads");Check(File.ReadAllText(System.IO.Path.Combine(f.Path,"tracked.txt"))=="after\n","worktree changed");Check(!File.Exists(System.IO.Path.Combine(f.Path,"external-ran"))&&!File.Exists(System.IO.Path.Combine(f.Path,"monitor-ran"))&&!File.Exists(System.IO.Path.Combine(f.Path,"textconv-ran")),"Git executed external diff/textconv/fsmonitor");Git(f.Path,"-c core.fsmonitor=false add -- tracked.txt");Check((await ws.ExecuteAsync("git_diff",J(new{scope="staged"}),CancellationToken.None)).Contains("+after"),"staged patch missing");File.WriteAllText(System.IO.Path.Combine(f.Path,"tracked.txt"),new string('x',80000));string huge=await ws.ExecuteAsync("git_diff","{}",CancellationToken.None);Check(huge.Contains("截断")&&huge.Length<26000,"unbounded diff");}}});
Run("read only Git refuses clean and process filters from local included and worktree config",async delegate{
using(var f=new Folder()){
string executable=Path.Combine(f.Path,"filter-probe.exe");File.Copy(System.Reflection.Assembly.GetExecutingAssembly().Location,executable);
string filterCommand=executable.Replace('\\','/');if(filterCommand.Contains(" "))filterCommand="\""+filterCommand+"\"";
var violations=new List<string>();
foreach(string tool in new[]{"git_status","git_diff"})foreach(string filter in new[]{"clean","process"})foreach(string config in new[]{"local","include","worktree"}){
string label=tool+"/"+filter+"/"+config,root=Path.Combine(f.Path,tool+"-"+filter+"-"+config);Directory.CreateDirectory(root);Git(root,"init -q");Git(root,"config user.name Fixture");Git(root,"config user.email fixture@example.invalid");
string tracked=Path.Combine(root,"tracked.txt");File.WriteAllText(tracked,"before\n");Git(root,"add -- tracked.txt");Git(root,"commit -qm baseline");File.WriteAllText(tracked,"after!\n");File.SetLastWriteTimeUtc(tracked,DateTime.UtcNow.AddSeconds(2));File.WriteAllText(Path.Combine(root,".gitattributes"),"tracked.txt filter=fixture\n");
string selector="";if(config=="include"){Git(root,"config include.path filter.conf");selector="--file .git/filter.conf ";}else if(config=="worktree"){Git(root,"config extensions.worktreeConfig true");selector="--worktree ";}
Git(root,"config "+selector+"filter.fixture."+filter+" "+WindowsCommandRunner.Quote(filterCommand));byte[] originalConfig=File.ReadAllBytes(Path.Combine(root,".git","config"));byte[] index=File.ReadAllBytes(Path.Combine(root,".git","index"));
using(var ws=new AgentWorkspace(root)){ws.PlanMode=true;var permission=new AgentPermissionRuntime();permission.Add(new AgentPermissionRule{Action="read",Resource="**",Effect=AgentPermissionEffect.Allow});ws.ConfigureKernel(permission,null);string result=await ws.ExecuteAsync(tool,"{}",CancellationToken.None);
if(File.Exists(Path.Combine(root,"filter-ran.txt")))violations.Add(label+" executed a filter with read permission only");
if(!result.StartsWith("错误：")||!result.Contains("过滤器"))violations.Add(label+" did not explain the unsafe filter");
Check(originalConfig.SequenceEqual(File.ReadAllBytes(Path.Combine(root,".git","config"))),label+" changed config");Check(index.SequenceEqual(File.ReadAllBytes(Path.Combine(root,".git","index"))),label+" changed index");Check(File.ReadAllText(tracked)=="after!\n",label+" changed worktree");}
}
Check(violations.Count==0,String.Join("; ",violations));
}});
Run("Git non repository and missing CLI are actionable",async delegate{using(var f=new Folder())using(var ws=new AgentWorkspace(f.Path)){Check((await ws.ExecuteAsync("git_status","{}",CancellationToken.None)).Contains("Git 仓库"),"non repo not explained");Git(f.Path,"init -q");string previous=Environment.GetEnvironmentVariable("PATH");try{Environment.SetEnvironmentVariable("PATH","");Check((await ws.ExecuteAsync("git_status","{}",CancellationToken.None)).Contains("Git CLI"),"missing CLI not explained");}finally{Environment.SetEnvironmentVariable("PATH",previous);}}});
Run("Git linked worktree uses verified metadata while confining files",async delegate{using(var f=new Folder()){Git(f.Path,"init -q");Git(f.Path,"config user.name Fixture");Git(f.Path,"config user.email fixture@example.invalid");File.WriteAllText(System.IO.Path.Combine(f.Path,"tracked.txt"),"baseline\n");Git(f.Path,"add -- tracked.txt");Git(f.Path,"commit -qm baseline");Git(f.Path,"worktree add -qb feature linked");File.WriteAllText(System.IO.Path.Combine(f.Path,"parent-secret.txt"),"outside workspace");string linked=System.IO.Path.Combine(f.Path,"linked");File.WriteAllText(System.IO.Path.Combine(linked,"tracked.txt"),"worktree edit\n");using(var ws=new AgentWorkspace(linked)){string status=await ws.ExecuteAsync("git_status","{}",CancellationToken.None);Check(status.Contains("tracked.txt")&&status.Contains("feature"),status);Check(!status.Contains("parent-secret"),"parent files leaked");Check((await ws.ExecuteAsync("git_diff","{}",CancellationToken.None)).Contains("worktree edit"),"linked diff missing");Check((await ws.ExecuteAsync("git_status",J(new{path="../"}),CancellationToken.None)).StartsWith("错误："),"worktree traversal accepted");}string pointer=System.IO.Path.Combine(linked,".git");File.SetAttributes(pointer,FileAttributes.Normal);File.WriteAllText(pointer,"gitdir: "+System.IO.Path.Combine(f.Path,".git"));using(var ws=new AgentWorkspace(linked))Check((await ws.ExecuteAsync("git_status","{}",CancellationToken.None)).StartsWith("错误："),"arbitrary external Git pointer accepted");}});
Run("Git timeout and cancellation kill complete process trees",async delegate{using(var f=new Folder()){
string executable=System.IO.Path.Combine(f.Path,"git.exe");File.Copy(System.Reflection.Assembly.GetExecutingAssembly().Location,executable);string previous=Environment.GetEnvironmentVariable("PATH");
try{Environment.SetEnvironmentVariable("PATH",f.Path);foreach(bool cancel in new[]{false,true}){
foreach(string marker in Directory.EnumerateFiles(f.Path,"*.pid"))File.Delete(marker);
using(var ct=new CancellationTokenSource()){
var reading=Task.Run(()=>AgentGitTools.Read("git_status",f.Path,f.Path,"unstaged",10,cancel?15:1,ct.Token));
if(cancel){var ready=Stopwatch.StartNew();while(!File.Exists(System.IO.Path.Combine(f.Path,"fake-git-parent.pid"))&&!reading.IsCompleted&&ready.ElapsedMilliseconds<5000)await Task.Delay(10);if(!File.Exists(System.IO.Path.Combine(f.Path,"fake-git-parent.pid"))){ct.Cancel();try{await reading;}catch(OperationCanceledException){}throw new Exception("cancellation fixture did not create its owned tree");}ct.CancelAfter(700);}
try{await reading;throw new Exception("expected timeout/cancel");}catch(OperationCanceledException){Check(cancel,"unexpected cancellation");}catch(ArgumentException e){Check(!cancel&&e.Message.Contains("超时"),e.Message);}}
foreach(string name in new[]{"fake-git-parent.pid","fake-git-child.pid"}){
string marker=System.IO.Path.Combine(f.Path,name);Check(File.Exists(marker),"timeout fixture process was never started: "+name);
int pid=Int32.Parse(File.ReadAllText(marker));try{using(var proc=Process.GetProcessById(pid))Check(proc.HasExited,"Git child survived cancellation/timeout");}catch(ArgumentException){}
}
}
// Process exit and release of Windows executable mappings are separate conditions.
// Assert both deaths above immediately, then wait only for this owned file's release.
await DeleteReleasedGitFixture(executable);
}finally{Environment.SetEnvironmentVariable("PATH",previous);}
}});
Console.WriteLine(failures==0?"All project tool tests passed.":"Failures: "+failures);return failures==0?0:1;}
[System.Runtime.InteropServices.DllImport("kernel32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode,SetLastError=true)]static extern bool CreateHardLink(string path,string existing,IntPtr security);
static async Task DeleteReleasedGitFixture(string path){var budget=Stopwatch.StartNew();while(true){try{File.Delete(path);return;}catch(Exception e){int code=e.HResult&0xffff;bool locked=(e is IOException&&code==32)||(e is UnauthorizedAccessException&&code==5);if(!locked||budget.ElapsedMilliseconds>=5000)throw;}await Task.Delay(10);}}
sealed class Folder:IDisposable {internal readonly string Path=System.IO.Path.GetFullPath(System.IO.Path.Combine("work","project-tools-"+Guid.NewGuid().ToString("N")));internal Folder(){Directory.CreateDirectory(Path);}public void Dispose(){string parent=System.IO.Path.GetFullPath("work")+System.IO.Path.DirectorySeparatorChar;if(!Path.StartsWith(parent,StringComparison.OrdinalIgnoreCase))throw new Exception("Unsafe fixture cleanup");foreach(string file in Directory.EnumerateFiles(Path,"*",SearchOption.AllDirectories))File.SetAttributes(file,FileAttributes.Normal);Directory.Delete(Path,true);}}
